import ajvModule from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface SchemaValidationIssue {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  params?: object;
  message?: string;
}

interface CompiledSchemaValidator {
  (toolInput: Record<string, unknown>): boolean | PromiseLike<unknown>;
  errors?: SchemaValidationIssue[] | null;
}

interface SchemaCompiler {
  compile(schema: Record<string, unknown>): CompiledSchemaValidator;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  compiledValidator?: CompiledSchemaValidator;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaCompiler = createSchemaCompiler();
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, CompiledSchemaValidator>();

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const compiledValidator =
      typeof definition === 'function'
        ? undefined
        : compileInputSchema(this.schemaCompiler, resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, compiledValidator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validator = this.resolveValidator(tool);
    if (!validator(input)) {
      return buildSchemaRejection(name, validator.errors ?? []);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private resolveValidator(tool: StoredTool): CompiledSchemaValidator {
    if (tool.compiledValidator) return tool.compiledValidator;
    const {name, inputSchema} = this.resolveDefinition(tool.definitionSource);
    const cached = this.dynamicValidators.get(inputSchema);
    if (cached) return cached;
    const compiled = compileInputSchema(this.schemaCompiler, name, inputSchema);
    this.dynamicValidators.set(inputSchema, compiled);
    return compiled;
  }

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }
}

type SchemaCompilerConstructor = new (options: Record<string, unknown>) => SchemaCompiler;

function createSchemaCompiler(): SchemaCompiler {
  const CompilerConstructor = resolveSchemaCompilerConstructor(ajvModule);
  return new CompilerConstructor({
    allErrors: true,
    strict: false,
    validateFormats: false,
    format: false,
    jsonPointers: true,
    logger: false,
  });
}

function resolveSchemaCompilerConstructor(ajvExport: unknown): SchemaCompilerConstructor {
  if (isSchemaCompilerConstructor(ajvExport)) return ajvExport;
  const defaultExport = readDefaultExport(ajvExport);
  if (isSchemaCompilerConstructor(defaultExport)) return defaultExport;
  throw new Error('Unable to resolve Ajv constructor');
}

function readDefaultExport(ajvExport: unknown): unknown {
  if (typeof ajvExport !== 'object' || ajvExport === null) return undefined;
  return 'default' in ajvExport ? ajvExport.default : undefined;
}

function isSchemaCompilerConstructor(ajvExport: unknown): ajvExport is SchemaCompilerConstructor {
  return typeof ajvExport === 'function';
}

function compileInputSchema(
  compiler: SchemaCompiler,
  toolName: string,
  inputSchema: Record<string, unknown>
): CompiledSchemaValidator {
  try {
    if (inputSchema['$async'] === true) throw new Error('Async tool schemas are not supported');
    return compiler.compile(inputSchema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${toolName}"`, {cause: error});
  }
}

function buildSchemaRejection(toolName: string, validationErrors: SchemaValidationIssue[]): ToolResponse {
  log.warn('tool', 'schema validation failed', {
    name: toolName,
    failures: validationErrors.map(issue => ({path: failingFieldPath(issue), constraint: issue.keyword})),
  });
  const summary = validationErrors.map(formatValidationIssue).join('; ');
  return {result: `Invalid input for tool "${toolName}": ${summary}`};
}

function formatValidationIssue(issue: SchemaValidationIssue): string {
  return `${failingFieldPath(issue)}: ${String(issue.message)}`;
}

function failingFieldPath(issue: SchemaValidationIssue): string {
  const basePath = resolveBasePath(issue);
  const missingProperty = issue.keyword === 'required' ? extractMissingProperty(issue.params) : undefined;
  const missingSuffix = missingProperty ? `/${missingProperty}` : '';
  return `${basePath}${missingSuffix}` || '/';
}

function resolveBasePath(issue: SchemaValidationIssue): string {
  if (issue.instancePath !== undefined) return issue.instancePath;
  return issue.dataPath ?? '';
}

function extractMissingProperty(params: object | undefined): string | undefined {
  if (!params || !('missingProperty' in params)) return undefined;
  return String(params.missingProperty);
}

